package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSoDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuuxun Quddus (Ruku & Sujuud)", "(Eebbe) waa nasahane, xurmo iyo qadarin, Eebaha Malaa'igta iyo Ruuxa (Jibriil).", "In rukuuc iyo sujuud.", "Nebigu ﷺ wuxuu ku akhriyey rukuuc iyo sujuud."),
        "dua_sujood_dhanbi_kullah" to DuaText("In Sujood: i cafi dembiyadayda oo dhan", "Allahayow dambigayga oo dhan iga dhaaf – yar iyo weyn, kan hore iyo kan dambe, mid cad iyo waxa qarsoonba.", "In sujuud.", "Sujuudu waa meel duco laga jawaabo."),
        "dua_sujood_ridaka" to DuaText("Qaxooti Raalligaaga", "Illahow waxaan kaa magan galay raali ahaanshiyahaaga cadhadaada, cafiskaagana waxaan kaa magan galayaa. Kuma ammaani karo si buuxda; Waxaad tahay sidaad isu ammaantay.", "Sujuud - Caa'isha (RA) waxay maqashay Nabiga ﷺ oo leh sidan.", "Sujuud ducadii nabiga ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Cibaado kasta oo af, muruq iyo maalba leh Allaah baa iska leh. Asalaamu calaykum, Nabiyow, naxariista Eebe iyo naxariistiisa. Asalaamu Calaykum Waraxmatulaahi Wabarakaatuh. Waxaan ka marag kacayaa inuusan jirin cid xaq u leh in la caabudo Alle mooyee, waxaana markhaati ka ah in Muxammad ﷺ uu yahay addoonkiisii ​​iyo Rasuulkiisii.", "Fadhi kasta - waxaa wariyay Cabdullaahi ibnu Mascuud (RA) (dhaqanka Xanafiyada).", "Nabigu ﷺ waxa u baray sida suurada quraanka kariimka ah."),
        "dua_sajdah_tilawah" to DuaText("Sajdah Akhriska", "Wajigaygu wuxuu u sujuuday Eebaha abuuray oo u soo saaray maqalkiisa iyo aragiisa xooggiisa iyo xooggiisa.", "In la sujuudo akhrinta.", "Nabigu ﷺ waxa uu sidaa ku yidhi sujuudkii akhrinta habeenkii."),
        "dua_after_witr" to DuaText("Kadib Witr", "Subxaana watacaalaa Boqorka Quduuska ah.", "Saddex jeer ka dib salaamkii witri, codkiina kor u qaaday mar saddexaad.", "Nabigu ﷺ waxa uu yidhi wit ka dib."),
        "dua_tahajjud_nur" to DuaText("Ducada Furitaanka Tahajjud", "Alloow mahad adigaa iska leh; Adaa arzuqi samooyinka, dhulka iyo waxa ku dhex jira. Mahad adigaa iska leh; Waxaad tahay iftiinka samooyinka, dhulka iyo waxa ku jira oo dhan. Mahad adigaa iska leh; Adigaa run ah, balantaadu waa run, la kulankaaga waa run, hadalkaagu waa run, Jannada waa run, naartana waa run, Nabiguna waa run, Muxammad ﷺ waa run, Saacadduna waa xaq.", "Marka la bilaabayo salaada habeenka (tahajjud) (qaybta furitaanka ee ducada).", "Nebigu ﷺ wuxuu akhriyey kan tahajjudka u kacaya (ducada buuxda waxay ku jirtaa al-Bukhaari)."),
        "dua_rabba_jibrail" to DuaText("Igu Hagaha Arimaha La Isku Haysto", "Eebbow Jibriil, Mikaa’iil iyo Israafiil, Abuuray Cirka iyo Dhulka, Maqan iyo Waxyaala og. Waxaad kala xukumi addoomadaada dhexdooda waxay isku khilaafeen. igu hanuun idankaaga xaqa ah waxa la isku khilaafay. 021-047 Waxaad ku Hanuunin Cidiid Doonto Jid Toosan.", "Bilawga tahajjudka - si loogu hanuuniyo xaqa iyada oo la isku khilaafay.", "Nebigu ﷺ waxa uu bilaabay ducadan habeenimo."),
        "dua_going_to_mosque_nur" to DuaText("Tagitaanka Masjidka (Duca Nuur)", "Alloow nuur qalbigayga geli, iftiinka indhahayga, dhegahayga nuur, iftiinka midigtayda, iftiinkayga bidixda, nuurkayga korkayga, iftiinkayga hoostiisa, iftiinkayga hortayda, iftiinka iga dambeeya, oo ii iftiimi.", "Isagoo aadaya masaajidka Fajarka.", "Nebigu ﷺ wuxuu akhriyey tan markii uu u baxayay salaadda."),
        "dua_waswasa_salah" to DuaText("Waswasa Inta lagu jiro Saalax (Khinzab)", "Illahay baan ka magan galay shaydaanka la nacladay.", "Marka ay xansha shaydaanku yimaaddo salaadda, magan gal oo si fudud ugu tufo bidix saddex jeer.", "Cuthmaan bin Abil-Caas (RA) ayaa saas yeelay, xantiina waa ka baxday."),
        "dua_alimal_ghayb" to DuaText("Eeg waxa maqan", "Alloow og waxa maqan iyo waxa la arkayba, abuuraha samooyinka iyo dhulka, Eebbaha wax walba maamula. Waxaan ka marag kacayaa inaan adiga mooyee ilaah kale jirin. Waxaan kaa magan galay xumaanta naftayda iyo sharka shaydaanka iyo shirkigiisa.", "Subaxdii, maqribkii iyo hurdada ka hor - Nabigu ﷺ wuxuu baray Abuu Bakar (RA).", "Ka ilaalinta xumaanta nafta iyo shaydaanka."),
        "dua_fitratil_islam" to DuaText("Fitrada Islaamka korkeeda", "Waxaan ku galnay subaxdii fitrada islaamka, qawlkii daacada ahaa, waxaan dul galnay diintii nabigeena Muxamed ﷺ iyo dariiqii aabaheen Ibraahiim (AS), oo toosan oo muslim ah, kana mid ahayn mushrikiinta.", "Subaxdii.", "Subax walba oo iimaanka la cusboonaysiiyo."),
        "dua_amsayna_fitrah" to DuaText("Habeenka Fitrada Islaamka", "Waxaan galnay maqribkii fitraddii islaamka, qawlkii ikhlaasnaa, diintii Nabigeena Muxamed ﷺ iyo dariiqii aabbaheen Ibraahim (AS), oo toosan oo muslim ah, mushrikiintana ka mid ahayn.", "Fiidkii.", "Dib u cusboonaysiinta iimaanka habeen walba."),
        "dua_tahleel_10_fajr" to DuaText("Toban Tahliil Kadib Fajr iyo Maghrib", "Ma jiro cid xaq u leh in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin. Xukunka isagaa iska leh mahadna isagaa leh. Isagaa wax nooleeya waxna dila, wax walbana isagaa kara.", "Toban jeer ka dib Fajar (iyo Maghrib), ka hor intaadan ka dhaqaaqin fadhigaaga ama hadalkaaga.", "Toban camal oo wanaagsan, toban danbi waa la tirtiray, toban darajo oo kor loo qaaday, lagana ilaalinayo shaydaan maalintii oo dhan."),
        "dua_la_hawla_kanz" to DuaText("Hantida Jannada", "Xoog iyo awood ma jiro Allaah mooyee.", "Badanaa, mar walba.", "Waa mid ka mid ah kheyraadka Jannada."),
        "dua_four_beloved_words" to DuaText("Afarta Kalmadood Ee Loogu Jecelyahay", "Subxaanallaah, mahad oo dhan Allaah ayaa iska leh, xaqna lagu caabudaa ma jiro Allaah mooyee, Allaah ayaana weyn.", "Kalmada Alle ugu jecelyahay.", "Waxay nabiga ﷺ kaga qaalisan yihiin wax kasta oo qorraxdu ku soo baxdo."),
        "dua_two_light_words" to DuaText("Laba Kalmadood Oo Carrabka Ku Iftiimaya", "Allaah ayaa mahad oo dhan iska leh; Subxaanallaah.", "Iftiin carrabka, culusna Miisaanka.", "Eebaha Raxmaanka ah ku jecelyahay, Carrabka u fudud, Miisaankana ku culus. (Xadiiskii u dambeeyay ee Bukhaari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikraam", "Lahaanshahaaga haybad iyo karaamow!", "Ku hay ducada - tilmaanta Nabiga ﷺ.", "Nabigu ﷺ wuxuu yidhi: Qabso ‘Ya Dhal-Jalali wal-Ikram’."),
        "dua_sleep_wadatu_janbi" to DuaText("Magacaaga Ayaan Ku Dhigay", "Rabbiyow, magacaaga ayaan dhinacayga ku jiifsadaa, Oo magacaaga ayaan ku kici doonaa. Haddaad naftayda qaado u naxariiso, haddaad sii daysona u dhawr sidaad addoommadaada xaqa ah u dhawrto.", "Ka dib markii ay boorka sariirta ka dhufatay oo jiifsatay.", "In qofku hurdo ka hor nafta loo dhiibo."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Nafteyda Adaa Abuuray", "Allow adigaa naftayda abuuray oo adaa qaadi doona. Geerideeda iyo nolosheeda adigaa iska leh. Haddaad noolayso iska ilaali, haddaad dishona cafi. Allahayow waxaan ku waydiisanayaa wanaag.", "Hurdada ka hor - waxaa wariyey Ibnu Cumar (RA).", "Nebigu ﷺ waxa uu faray in uu sidaas yidhi marka la seexanayo."),
        "dua_sleep_atamana" to DuaText("Mahadnaqa Hurdada Ka Hor", "Mahad oo dhan waxay u sugnaatay Allaha na quudiyey, na waraabiyey, na siiyey, oo hoy na siiyey. Immisa ayaa jira oo aan haysan cid ku filan ama hoy siisa.", "Marka aad seexanayso.", "Nebigu ﷺ ayaa sidaa yidhi markuu seexanayo."),
        "dua_sleep_rabbas_samawat" to DuaText("Eebbaha jannada - Bixi deyntayada", "Ilaahow, Eebaha Samooyinka, Dhulka iyo Carshiga wayn, Eebahanno ah Eebahanno, Eebahanno ah Eebahanno, Eebahanno, Eebahanno, Eebahanno, Eebahanno, Eebahanno, Eebahan Wax Walbahaa, Kala Bixiya Tawreed iyo Timir, Eebaha Tawreed, Injiil iyo Furqaanba. Waxaan kaa magan galay xumaanta wax kasta oo aad qabsato. Alloow adigaa ugu horreeya, wax kaa horreeyana ma jiro; Adigaa ah kan ugu dambeeya, wax kaa dambeeyana ma jiro; Adigu waxaad tahay Muujintii, wax kaa sarreeya ma jiraan; Adigu waxaad tahay mid qarsoon, wax kaa qarsoonna ma jiraan. Deymaha naga qabo oo faqriga naga xoreeya.", "Hurdo ka hor, u jiifso dhinaca midig - waxaa baray Fatimah (RA).", "Duco ka cafinta deynta iyo dhibka."),
        "dua_sleep_fear" to DuaText("Cabsida ama raaxo la'aanta hurdada", "Waxaan ka magan galnay kalimada Eebbe cadhadiisa iyo ciqaabtiisa, sharka addoomadiisa, iyo xaswaaska shaydaanka iyo imaatinka ay ii yimaadaan.", "Markaad dareento cabsi ama hurdo la'aan.", "Haddii uu sidaas sameeyo, taasi waxba isaga ma yeeli doonto."),
        "dua_waking_afani" to DuaText("Baraarugay: Nafta ayuu soo celiyay", "Mahad dhamaanteed waxay u sugnaatay Allahii jidhkayga wanaaga siiyay, nafteydana ii soo celiyay, iina ogolaaday inaan xuso.", "Marka la soo jeedo.", "Waad ku mahadsan tahay subax cusub."),
        "dua_allahu_rabbi" to DuaText("Allaah, Allaahu akbar", "Allaah, Allaahu waa Rabbigey; Isaga waxba lama wadaajiyo.", "Murugo ama murugo - Nebigu ﷺ wuxuu baray Asma bint Umays (RA).", "Qabashada tawxiidka xilliyada dhibka."),
        "dua_rahmataka_arju" to DuaText("Naxariistaada Ayaan Rajeynayaa", "Allow waa naxariistaada tan aan rajaynayo ee ha iga tagin nafteyda xataa il bibiqsi dartiis, arimahaygana toosi. Adiga mooyee ilaah kale ma jiro.", "Ducada qofka dhibaataysan (Daawat al-makrub).", "Nabigu ﷺ waxa uu ku magacaabay ducada qofka dhibaataysan."),
        "dua_against_enemy_ahzab" to DuaText("Ka Hortaga Ciidamada Cadawga", "Alloow kitaabka soo dajiyay, xisaabtiisuna deg-deg! Guuleysta xulufada. Alloow jabi oo rux.", "Ka soo horjeeda cadowga - ducada Battle of Confederates.", "Ducadii Nabiga ﷺ ee cadawga."),
        "dua_anta_adudi" to DuaText("Waxaad tahay Taageeradayda", "Allow adigaa ii hiili iyo gargaare. Adiga ayaan wax ku qorsheeyaa, adigaan ku hormarayaa adigaan ku dagaalamaa.", "Kahor tartan ama tartan weyn.", "Nebigu ﷺ wuxuu sidaa ku yidhi dagaal."),
        "dua_ikfinihim" to DuaText("Iga Filan Iyaga", "Alloow igu filan iyaga si kasta oo aad doonto.", "Ka soo horjeeda xumaanta kuwa daalimiinta ah - ducada wiilka ee sheekada dadka godka.", "Allaha ka badbaadiyay wiilkaas daalimiinta ah."),
        "dua_qadarullah" to DuaText("Marka Wax Xun Dhacdo", "Waana qadarkii Eebe, wuxuuna falay wuxuu doono.", "Marka wax aan fiicnayn ay dhacaan, halkii laga odhan lahaa 'haddii kaliya'.", "'Haddii kaliya' ayaa albaabka u furaya shaydaan."),
        "dua_ala_kulli_hal" to DuaText("Amaan xaalad kasta", "Mahad oo dhan Allaah ayaa iska leh xaalad kasta.", "Marka wax aan la jeclayn ay dhacaan.", "Nebigu ﷺ waxa uu sidaa yidhi isaga oo wajahaya wax aanu jeclayn."),
        "dua_dogs_barking" to DuaText("Eeyaha Maqalka Ayaa Ciyaan Habeenkii", "Illahay baan ka magan galay shaydaanka la nacladay.", "Markay maqlaan eeyaha way ciyaan ama dameerku ciyaan habeenkii.", "Waxay arkaan waxaydaan arkaynin."),
        "dua_leaving_home_adilla" to DuaText("Ka Qaxooti Dhufsanaanta", "Alloow waxaan kaa magan galayaa inaan dhumin ama la i hanuuniyo, oo aan simbiriirixan ama aan simbiriirixan, oo aanan xumaan ama la ii dulmin, yaanan doqonnimo u dhaqmin ama la ii dhaqmin.", "Markaad guriga ka baxayso - waxaa wariyay Ummu Salamah (RA).", "Nebigu ﷺ wuu akhrin jiray mar kasta oo uu gurigiisa ka baxayo."),
        "dua_ascending_descending" to DuaText("Kor u kaca oo soo degaya", "Eebe waa kan ugu wayn (marka la korayo). — Subxaanallaah (markuu soo degaya).", "Safarka, waxaad dhahdaa 'Allaahu Akbar' markaad kor u kacayso, 'SubhanAllah' markaad soo degayso.", "Dhaqankii Saxaabada (RA) marka la safrayo."),
        "dua_traveller_sahar" to DuaText("Ducada Safarka Kahor Waaberiga", "Dhegeyste ayaa maqlay (oo soo gudbiyay) mahadda Alle iyo nicmada uu inoogu deeqay. Eebow na raac oo noo yeel Nicmadaada - (Waxaan leeyahay) ka magangal Eebe Naarta.", "Safar, ka hor waaberiga.", "Nebigu ﷺ wuxuu sidaa yidhi ka hor waaberiga markuu safrayay."),
        "dua_zawwadakallah" to DuaText("Ku Socodka: Allaah Taqwa ha siiyo", "Alle taqwada safarkaaga ha kugu asturo, dambigaaga ha dhaafo, khayrkana ha kuu fududeeyo meel kasta oo aad joogto.", "Marka la sagootinayo musaafurka.", "Nebigu ﷺ wuxuu ducadan siiyay qof safar u baxayay."),
        "dua_traveller_to_resident" to DuaText("Socdaal ku taga Kuwa ka dambeeya", "Waxaan kugu wakiinsanayaa Allaah, kaas oo taladiisa aan la lumin.", "Wuxuu yidhi ninkii socotada ahaa markuu reerka macsalaamaynayey.", "Nabad gelyada qoyskana Alle u wakiishay."),
        "dua_entering_village" to DuaText("Gelida Magaalo ama Tuulo", "Eebaha todobada samo iyo hadhkooda, Eebaha todobada dhul iyo waxa ay xanbaarsan yihiin, Eebaha shayaadiinta iyo waxay dhuminayaan, Eebaha dabaysha iyo waxay kala firdhiyaan. Waxaan ku waydiisanaynaa wanaaga magaaladan iyo dadkeedaba, waxaana kaa magan galnay xumaanteeda, xumaanteeda iyo xumaanta waxa ku sugan.", "Kahor intaadan gelin magaalo ama magaalo.", "Nebigu ﷺ wuu akhriyi jiray mar kasta oo uu damco inuu magaalo galo."),
        "dua_vehicle_stumbles" to DuaText("Marka Gaadhigu Turunturoodo", "Magaca Allaah.", "Marka buurta ama gaadhigu simbiriiro ama turunturoodo, halkii laga odhan lahaa ‘Shaydaan ha halaagsamo’.", "Bismillah oo la dhaho waxay Shaydaanka ka dhigtaa mid yar oo duqsiga le'eg."),
        "dua_ajz_kasal_haram" to DuaText("Daciifnimada iyo gabowga ka magan galo", "Allahayow waxaan kaa magan galay tabar darrida iyo caajisnimada, fulaynimada iyo gabowga, fitnada nolol iyo geeri iyo cadaabka qabriga.", "Duco maalinle ah oo dhammaystiran.", "Ducadii nabiga ﷺ uu sameeyay marar badan."),
    )
}
